const fs = require('fs');

const readme = fs.readFileSync('README.md', 'utf8');
const headings = readme
  .split(/\r?\n/)
  .filter((line) => line.startsWith('#'))
  .join('\n');

fs.writeFileSync('INDEX.md', headings + (headings ? '\n' : ''));
console.log('INDEX.md written');

